@startuml

class Airline {
  + Name : string
}

class Salesperson {
  + Name : string
  + EmployeeID : string
}

class Contract {
  + ContractID : string
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + AcquisitionID : string
  + Price : double
  + DeliveryDate : date
  + Options : string
}

class Airplane {
  + Model : string
  + SerialNumber : string
}

Airline "1" -- "0..*" Contract
Airline "0..1" -- "0..1" Airline : motherOf
Airline "0..1" -- "0..1" Airline : daughterOf
Salesperson "1" -- "0..*" Contract
Contract "1" *-- "1..*" Acquisition
Acquisition "1" -- "1" Airplane
Airplane "1" -- "0..*" Acquisition

@enduml

